{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--card:#ffffff;--muted:#6b7280;--accent:#6b4eff;--accent-2:#ff7ab6;--glass:rgba(255,255,255,0.6);font-family:Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#f7f8fb);color:#0f172a}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{max-width:980px;margin:28px auto;padding:36px;border-radius:14px;background:linear-gradient(180deg,rgba(107,78,255,0.06),rgba(255,122,182,0.03));box-shadow:0 6px 30px rgba(15,23,42,0.04);position:relative;overflow:hidden}
    .pattern{position:absolute;right:-120px;top:-60px;width:420px;height:420px;opacity:0.15}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted);line-height:1.5}
    .grid{display:grid;grid-template-columns:1fr 380px;gap:22px;margin-top:22px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(12,18,28,0.04)}
    .muted{color:var(--muted);font-size:14px}
    .session-planner label{display:block;font-weight:700;margin-top:12px}
    select,input[type=text],textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e9ef;margin-top:8px;font-size:14px}
    .controls{display:flex;gap:8px;margin-top:12px}
    button{background:var(--accent);color:white;padding:10px 12px;border-radius:8px;border:0;cursor:pointer}
    .secondary{background:#eef2ff;color:var(--accent);border:1px solid rgba(107,78,255,0.12)}
    .result{white-space:pre-wrap;background:#f8fafc;padding:12px;border-radius:8px;border:1px dashed #e6eefc;margin-top:12px}
    footer.note{max-width:980px;margin:22px auto;color:var(--muted);font-size:13px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;text-decoration:none;font-weight:700}
    /* small */
    @media(max-width:900px){.grid{grid-template-columns:1fr}.pattern{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">TP</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html" style="color:var(--accent)">About</a>
      <a href="specialties.html">Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="fees.html">Investment</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <defs>
          <pattern id="p1" x="0" y="0" width="20" height="20" patternUnits="userSpaceOnUse">
            <rect width="10" height="10" fill="#6b4eff" opacity="0.12"></rect>
            <circle cx="15" cy="5" r="3" fill="#ff7ab6" opacity="0.14"></circle>
          </pattern>
        </defs>
        <rect width="200" height="200" fill="url(#p1)"/>
      </svg>

      <h1>Care that meets you where things feel tangled</h1>
      <p class="lead">I'm a licensed clinician focused on helping adults navigate transitions, recurring patterns, and the kind of stress that quietly reshapes your days. Sessions are collaborative — we name what matters and practice manageable ways to move forward.</p>

      <div class="grid">
        <div class="card">
          <h3 style="margin-top:0">About me</h3>
          <p class="muted">I work with people who are balancing career demands, relationships, parenting, and the shape of their inner life. My approach blends evidence-informed tools with pragmatic, individualized planning.</p>
          <p style="margin-top:12px;color:var(--muted)">Licensure, professional note: I hold appropriate clinical licensure and follow professional ethics. Therapy is confidential within clinical and legal limits.</p>
          <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
        </div>

        <aside class="card session-planner" aria-labelledby="planner-heading">
          <h4 id="planner-heading">Session Planner</h4>
          <p class="muted">Build a short plan to bring to your first meeting — then copy the summary to share or save.</p>

          <label for="focus">Primary focus for sessions</label>
          <select id="focus">
            <option>Managing daily overwhelm</option>
            <option>Relationship communication</option>
            <option>Career transitions and decisions</option>
            <option>Grief and life shifts</option>
            <option>Self-regulation and anxiety</option>
          </select>

          <label for="rhythm">Session rhythm</label>
          <select id="rhythm">
            <option value="weekly">Weekly</option>
            <option value="biweekly">Every other week</option>
            <option value="monthly">Monthly check-in</option>
          </select>

          <label for="length">Session length</label>
          <select id="length">
            <option>50 minutes</option>
            <option>75 minutes</option>
            <option>25 minutes (brief)</option>
          </select>

          <label for="goals">One short goal you'd like to name</label>
          <input id="goals" type="text" placeholder="e.g., calm my morning routine" />

          <div class="controls">
            <button id="build">Create plan</button>
            <button id="copy" class="secondary">Copy summary</button>
          </div>

          <div id="planResult" class="result" aria-live="polite">Your personalized plan will appear here.</div>

          <script>
            (function(){
              const build=document.getElementById('build');
              const copyBtn=document.getElementById('copy');
              const result=document.getElementById('planResult');
              function summarize(){
                const focus=document.getElementById('focus').value;
                const rhythm=document.getElementById('rhythm').value;
                const length=document.getElementById('length').value;
                const goals=document.getElementById('goals').value.trim()||'(no short goal added)';
                const lines=[
                  'Session Planner — Personal Summary',
                  'Primary focus: '+focus,
                  'Preferred rhythm: '+rhythm,
                  'Session length: '+length,
                  'Short goal: '+goals,
                  '',
                  'What I hope to bring to session: a clear example or recent moment related to the focus; one small step I can try between sessions.'
                ];
                return lines.join('\n');
              }
              build.addEventListener('click',()=>{result.textContent=summarize();});
              copyBtn.addEventListener('click',async()=>{
                try{
                  await navigator.clipboard.writeText(summarize());
                  copyBtn.textContent='Copied';
                  setTimeout(()=>copyBtn.textContent='Copy summary',1200);
                }catch(e){
                  result.textContent='Could not copy automatically. Select and copy this text manually:\n\n'+summarize();
                }
              });
            })();
          </script>

        </aside>
      </div>

    </section>

    <section class="card" style="max-width:980px;margin:18px auto;padding:18px">
      <h3 style="margin-top:0">Professional boundaries & confidentiality</h3>
      <p class="muted">Conversations in therapy are confidential, with important exceptions required by law (harm to self/others, abuse of a minor/elder). I can discuss limits of confidentiality during our first appointment. Therapy is not emergency care; if you are in crisis or danger, call local emergency services or a crisis line.</p>

      <h4 style="margin-top:12px">Scope & collaboration</h4>
      <p class="muted">I provide psychotherapy and brief coaching for adults. If your needs are outside my scope, I will recommend appropriate community or medical resources. Our work is collaborative; I aim to support you in making decisions that match your values and life context.</p>
    </section>

  </main>

  <footer class="note">Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="book.html">Book a consult</a></footer>
</body>
</html>"}   
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Areas of Focus — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--muted:#5b6674;--accent:#0f7cff;--card:#fbfbff;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial}
    body{margin:0;background:linear-gradient(180deg,#fff,#f8fbff);color:#071023}
    header{display:flex;justify-content:space-between;padding:18px 28px;align-items:center}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:980px;margin:20px auto;padding:16px}
    h1{margin:0 0 8px}
    .intro{color:var(--muted);margin-bottom:18px}
    .list{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
    .tile{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 8px 22px rgba(11,20,40,0.04)}
    .tile h3{margin:0 0 8px}
    .muted{color:var(--muted)}
    .wizard{margin-top:20px;background:white;padding:14px;border-radius:12px;border:1px solid #eef4ff}
    .wizard .step{display:none}
    .wizard .step.active{display:block}
    .buttons{display:flex;gap:8px;margin-top:12px}
    button{background:var(--accent);color:white;padding:10px 12px;border-radius:8px;border:0;cursor:pointer}
    .secondary{background:#eef6ff;color:var(--accent)}
    textarea{width:100%;min-height:120px;border-radius:8px;border:1px solid #e9f0ff;padding:10px}
    @media(max-width:760px){.list{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;background:linear-gradient(90deg,#0f7cff,#6b4eff);border-radius:10px;color:white;display:flex;align-items:center;justify-content:center;font-weight:700">SP</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Practical, collaborative care</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html" style="color:var(--accent)">Areas</a>
      <a href="approach.html">How I Work</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Areas I support</h1>
    <p class="intro">Common themes people bring: decisions that shift daily life, patterns that keep returning, and interpersonal strain. Below are typical areas of focus and what we might notice in early sessions.</p>

    <section class="list" aria-label="specialty list">
      <article class="tile">
        <h3>Transitions & Decisions</h3>
        <p class="muted">Sorting through career, relationship, or family changes with values-based clarity and practical steps.</p>
      </article>
      <article class="tile">
        <h3>Stress, Overwhelm & Burnout</h3>
        <p class="muted">Working on pacing, boundaries, and small routines to reduce constant activation and preserve energy.</p>
      </article>
      <article class="tile">
        <h3>Relationships & Communication</h3>
        <p class="muted">Clearer requests, boundary-setting, and reducing reactivity — whether in partnership, family, or work contexts.</p>
      </article>
      <article class="tile">
        <h3>Adjustment after Loss</h3>
        <p class="muted">Grief and life reorientation — creating ways to remember, to adapt, and to find steadying practices.</p>
      </article>
    </section>

    <section class="wizard" aria-labelledby="wizard-heading">
      <h2 id="wizard-heading">Quick Self-Screen: What to bring to a first session</h2>
      <p class="muted">This short, non-diagnostic checklist helps you notice patterns and create questions to discuss in a consultation.</p>

      <div id="wizard">
        <div class="step active" data-step="1">
          <label><strong>1) What feels most pressing?</strong></label>
          <select id="q1">
            <option>Difficulty sleeping or tiredness</option>
            <option>Feeling easily overwhelmed</option>
            <option>Recurring conflict with someone</option>
            <option>Uncertainty about a major decision</option>
            <option>Low mood or loss of interest</option>
          </select>
        </div>

        <div class="step" data-step="2">
          <label><strong>2) How long has this been happening?</strong></label>
          <select id="q2">
            <option>Less than a month</option>
            <option>1–6 months</option>
            <option>6 months — 2 years</option>
            <option>Longer than 2 years</option>
          </select>
        </div>

        <div class="step" data-step="3">
          <label><strong>3) What have you tried already?</strong></label>
          <textarea id="q3" placeholder="brief notes: e.g., talked with a friend, changed routine, tried meditation"></textarea>
        </div>

        <div class="step" data-step="4">
          <label><strong>4) What would success look like in 3 months?</strong></label>
          <input id="q4" type="text" placeholder="one short sentence" />
        </div>

        <div class="buttons">
          <button id="prev" class="secondary">Back</button>
          <button id="next">Next</button>
          <button id="generate" style="display:none">Create my list</button>
        </div>

        <div id="output" style="margin-top:12px"></div>
      </div>

      <script>
        (function(){
          const steps=[...document.querySelectorAll('#wizard .step')];
          let idx=0;
          const prev=document.getElementById('prev');
          const next=document.getElementById('next');
          const gen=document.getElementById('generate');
          const output=document.getElementById('output');

          function show(){
            steps.forEach((s,i)=>s.classList.toggle('active',i===idx));
            prev.style.display= idx>0 ? 'inline-flex' : 'none';
            next.style.display= idx<steps.length-1 ? 'inline-flex' : 'none';
            gen.style.display= idx===steps.length-1 ? 'inline-flex' : 'none';
          }
          show();

          next.addEventListener('click',()=>{ idx=Math.min(steps.length-1,idx+1); show(); });
          prev.addEventListener('click',()=>{ idx=Math.max(0,idx-1); show(); });

          gen.addEventListener('click',()=>{
            const a=document.getElementById('q1').value;
            const b=document.getElementById('q2').value;
            const c=document.getElementById('q3').value.trim()||'(none noted)';
            const d=document.getElementById('q4').value.trim()||'(no goal added)';
            const lines=['Notes to bring to consult:','- Most pressing: '+a,'- Duration: '+b,'- What tried: '+c,'- Short 3-month aim: '+d,'','Suggested questions to ask:','1) What types of support might fit this timeline?','2) What early steps can I try between sessions?','3) Are there any immediate safety concerns I should mention?'];
            output.innerHTML='<pre style="white-space:pre-wrap;background:#f7fbff;padding:12px;border-radius:8px">'+lines.join('\n')+'</pre>'+'<div style="margin-top:8px"><button id="copyQ" class="secondary">Copy questions</button></div>';
            document.getElementById('copyQ').addEventListener('click',async()=>{
              try{await navigator.clipboard.writeText(lines.join('\n'));document.getElementById('copyQ').textContent='Copied';setTimeout(()=>document.getElementById('copyQ').textContent='Copy questions',1200);}catch(e){alert('Copy not available — select and copy manually.');}
            });
          });
        })();
      </script>

    </section>

    <p style="margin-top:18px;color:var(--muted)">If something feels urgent or unsafe, please contact local emergency services or a crisis line. This tool is for conversation preparation, not a medical or crisis assessment.</p>
  </main>
</body>
</html>"}   
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>How I Work — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#556072;--accent:#9b6bff;--accent-2:#ff8fb3;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:linear-gradient(180deg,#fff,#fcfdff);color:#062033}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 26px}
    nav a{margin:0 9px;color:var(--muted);text-decoration:none}
    .container{max-width:980px;margin:18px auto;padding:18px}
    .lead{color:var(--muted);margin-bottom:10px}
    .flow{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .panel{background:#fff;padding:14px;border-radius:12px;box-shadow:0 8px 26px rgba(8,12,25,0.04)}
    .pill{display:inline-block;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white;padding:6px 10px;border-radius:999px;font-weight:700}
    .list{margin-top:12px}
    .list li{margin:8px 0;color:var(--muted)}
    .intake{margin-top:12px}
    .intake label{display:block;margin:10px 0 6px;font-weight:700}
    input[type=text],select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #eef2ff}
    .small{font-size:13px;color:var(--muted)}
    .wizard-deep .step{display:none}
    .wizard-deep .step.active{display:block}
    button{background:var(--accent);color:white;border:0;padding:10px 12px;border-radius:8px;cursor:pointer}
    .ghost{background:#f4f6fb;color:var(--muted)}
    @media(max-width:900px){.flow{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;background:linear-gradient(90deg,#9b6bff,#ff8fb3);border-radius:12px;color:white;display:flex;align-items:center;justify-content:center;font-weight:700">HW</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">A practical, evidence-aware approach</div>
      </div>
    </div>

    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="specialties.html">Areas</a>
      <a href="fees.html">Investment</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="container">
    <h1>How I work together with clients</h1>
    <p class="lead">Short-term focuses, longer-term partnership, and an emphasis on practical experiments. I blend structured strategies with moment-to-moment attention so sessions feel useful and grounded.</p>

    <div class="flow">
      <section class="panel">
        <div class="pill">Process</div>
        <ul class="list">
          <li><strong>Session 1:</strong> clarify concerns, set a short goal, and co-design a plan.</li>
          <li><strong>Weekly/biweekly work:</strong> a mix of skill practice, reflective exploration, and concrete steps.</li>
          <li><strong>Between-session experiments:</strong> small, measurable changes to test what helps.</li>
        </ul>

        <h3 style="margin-top:12px">What I ask of clients</h3>
        <ul class="list small">
          <li>Attend with a willingness to try small experiments.</li>
          <li>Bring brief notes when helpful (things you notice, one recent example of the challenge).</li>
          <li>Share any safety concerns so we can plan appropriate support.</li>
        </ul>

        <h3 style="margin-top:12px">Ethics & limits</h3>
        <p class="small">Notes on confidentiality: I keep session content private except in legal exceptions (harm, abuse, court orders). Therapy is not a substitute for emergency services or urgent medical care.</p>

      </section>

      <aside class="panel">
        <h4 style="margin-top:0">Deep Intake: Prepare detailed notes</h4>
        <p class="small">A step-by-step self-review to bring to an extended consultation. Non-diagnostic — meant to help you and the clinician orient quickly.</p>

        <div class="wizard-deep" id="deep">
          <div class="step active" data-step="1">
            <label>Brief description of what brings you here</label>
            <textarea id="d1" placeholder="Two or three sentences"></textarea>
          </div>
          <div class="step" data-step="2">
            <label>Examples (last 2 weeks)</label>
            <textarea id="d2" placeholder="Specific moments, interactions, or patterns"></textarea>
          </div>
          <div class="step" data-step="3">
            <label>What makes it better or worse?</label>
            <textarea id="d3" placeholder="Situations, times of day, people, coping strategies"></textarea>
          </div>
          <div class="step" data-step="4">
            <label>What matters most to you now?</label>
            <input id="d4" type="text" placeholder="Value or short aim (1 line)" />
          </div>

          <div style="margin-top:10px;display:flex;gap:8px">
            <button id="prevDeep" class="ghost">Back</button>
            <button id="nextDeep">Next</button>
            <button id="exportDeep" style="display:none">Export notes</button>
          </div>

          <div id="deepOut" style="margin-top:10px"></div>
        </div>

        <script>
          (function(){
            const steps=[...document.querySelectorAll('#deep .step')];
            let idx=0;const prev=document.getElementById('prevDeep'), next=document.getElementById('nextDeep'), exp=document.getElementById('exportDeep'), out=document.getElementById('deepOut');
            function show(){ steps.forEach((s,i)=>s.classList.toggle('active',i===idx)); prev.style.display=idx>0?'inline-flex':'none'; next.style.display=idx<steps.length-1?'inline-flex':'none'; exp.style.display=idx===steps.length-1?'inline-flex':'none'; }
            show();
            next.addEventListener('click',()=>{ idx=Math.min(steps.length-1,idx+1); show(); });
            prev.addEventListener('click',()=>{ idx=Math.max(0,idx-1); show(); });
            exp.addEventListener('click',async()=>{
              const a=document.getElementById('d1').value.trim()||'(no brief description)';
              const b=document.getElementById('d2').value.trim()||'(no examples)';
              const c=document.getElementById('d3').value.trim()||'(no modifiers noted)';
              const d=document.getElementById('d4').value.trim()||'(no priority noted)';
              const outText=['Detailed intake notes to bring to consultation:','- Brief description: '+a,'- Recent examples: '+b,'- What helps/worsens: '+c,'- Most important value/aim: '+d,'','Suggested starter questions:','• What would a short 6-week approach look like?','• Which immediate steps would be most important to try?','• What supports should we consider outside sessions?'].join('\n');
              out.innerHTML='<pre style="white-space:pre-wrap;background:#fbf7ff;padding:10px;border-radius:8px">'+outText.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')+'</pre><div style="margin-top:8px"><button id="copyDeep" class="ghost">Copy notes</button></div>';
              document.getElementById('copyDeep').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(outText);document.getElementById('copyDeep').textContent='Copied';setTimeout(()=>document.getElementById('copyDeep').textContent='Copy notes',1200);}catch(e){alert('Copy not available — select and copy manually.');}});
            });
          })();
        </script>

        <p class="small" style="margin-top:12px">This intake summary helps the clinician prepare. It is not a comprehensive assessment and does not replace emergency care. If you are experiencing an active crisis, call local emergency services.</p>

      </aside>
    </div>

    <section style="margin-top:18px;padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(155,107,255,0.06),rgba(255,143,179,0.03))">
      <h3 style="margin-top:0">Collaborative outcomes I aim for</h3>
      <ul class="list">
        <li>Clear, manageable steps that fit your life.</li>
        <li>Skills you can practice between sessions and feedback on what helps.</li>
        <li>Transparent conversation about scope, resources, and referrals when needed.</li>
      </ul>

      <p class="small">If we decide to work together, we'll set a short-term plan first and revisit it regularly. You are the expert on your life; my role is to offer clinical structure, observations, and practical experiments.</p>
    </section>

